begin;
-- Real synthetic sessions for member JWT fixtures; rows roll back with this test.
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path=extensions,public,private;
select no_plan();
update private.private_locations set verified_at=now() where profile_id::text like '10000000-%';
select ok(has_function_privilege('authenticated','public.create_group(text,text,text)','execute'),'group creation restored');
select ok(not has_function_privilege('anon','public.create_group(text,text,text)','execute'),'anonymous creation denied');
select ok(not has_table_privilege('authenticated','public.group_messages','insert'),'clients cannot forge message sender');
select ok(not has_function_privilege('authenticated','public.start_group_voice(uuid)','execute'),'voice cannot falsely claim connected transport');
insert into public.friendships(requester_id,addressee_id,status,responded_at) values
 ('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','accepted',now()),
 ('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','accepted',now());
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('test.group',public.create_group('Test group','Private group')::text,true);
select is((public.get_launch_capabilities()->>'permanentGroups')::boolean,true,'restored groups advertised independently from voice');
select is(jsonb_array_length(public.list_groups()),1,'owner sees own group');
select lives_ok($$select public.add_group_member(current_setting('test.group')::uuid,'10000000-0000-0000-0000-000000000002')$$,'owner invites accepted friend');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid))::text,true);
select is(jsonb_array_length(public.list_groups()),0,'outsider sees no group');
select throws_ok($$select public.add_group_member(current_setting('test.group')::uuid,'10000000-0000-0000-0000-000000000003','admin')$$,'42501','group_admin_required','NULL caller role does not bypass admin check');
select throws_ok($$select public.list_group_messages_page(current_setting('test.group')::uuid)$$,'42501','active_group_membership_required','outsider cannot read group messages');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select is(public.list_groups()->0->>'membershipStatus','invited','invitation is explicit pending consent');
select throws_ok($$select public.list_group_members(current_setting('test.group')::uuid)$$,'42501','active_group_membership_required','invitee cannot read roster before accepting');
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'accept')$$,'invitee accepts');
select is(jsonb_array_length(public.list_group_members(current_setting('test.group')::uuid)),2,'accepted member can read roster');
select throws_ok($$select public.group_action(current_setting('test.group')::uuid,'set_role','{"profileId":"10000000-0000-0000-0000-000000000002","role":"owner"}')$$,'42501','group_admin_required','member cannot self-promote');
select set_config('test.message',public.send_group_message_once(current_setting('test.group')::uuid,'Hello','73000000-0000-0000-0000-000000000001')::text,true);
select is(public.send_group_message_once(current_setting('test.group')::uuid,'Hello','73000000-0000-0000-0000-000000000001')::text,current_setting('test.message'),'lost acknowledgement retry preserves ID');
select throws_ok($$select public.send_group_message_once(current_setting('test.group')::uuid,'Different','73000000-0000-0000-0000-000000000001')$$,'23505','group_message_id_conflict','ID cannot be reused with different content');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select is(jsonb_array_length(public.list_group_messages_page(current_setting('test.group')::uuid)->'items'),1,'other member sees one confirmed message');
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'lock')$$,'owner can lock group');
select throws_ok($$select public.send_group_message_once(current_setting('test.group')::uuid,'Locked','73000000-0000-0000-0000-000000000002')$$,'42501','active_group_membership_required','locked group rejects writes');
select is(jsonb_array_length(public.list_group_messages_page(current_setting('test.group')::uuid)->'items'),1,'locked history remains readable');
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'unlock')$$,'owner can unlock group');
reset role;
insert into public.group_messages(id,group_id,sender_id,body,created_at)
select ('74000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,current_setting('test.group')::uuid,'10000000-0000-0000-0000-000000000002','History '||n,now()-interval '1 hour' from generate_series(1,65)n;
set local role authenticated;
select set_config('test.group_page',public.list_group_messages_page(current_setting('test.group')::uuid)::text,true);
select is(jsonb_array_length(current_setting('test.group_page')::jsonb->'items'),50,'group history bounded to 50');
select set_config('test.group_page2',public.list_group_messages_page(current_setting('test.group')::uuid,current_setting('test.group_page')::jsonb->'nextCursor')::text,true);
select is(jsonb_array_length(current_setting('test.group_page2')::jsonb->'items'),16,'equal-time cursor retains all older messages');
select is((select count(*) from jsonb_array_elements(current_setting('test.group_page')::jsonb->'items')a join jsonb_array_elements(current_setting('test.group_page2')::jsonb->'items')b on a->>'id'=b->>'id'),0::bigint,'group pages never overlap');
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'hide_message',jsonb_build_object('messageId',current_setting('test.message')))$$,'owner can moderate message');
reset role;
insert into public.blocks(blocker_id,blocked_id) values('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002');
set local role authenticated;
select is(jsonb_array_length(public.list_group_messages_page(current_setting('test.group')::uuid)->'items'),0,'blocked peer content is not readable in shared group');
select throws_ok($$select public.add_group_member(current_setting('test.group')::uuid,'10000000-0000-0000-0000-000000000002')$$,'42501','group_member_blocked','blocked member cannot be re-invited');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'leave')$$,'member can leave');
select throws_ok($$select public.list_group_messages_page(current_setting('test.group')::uuid)$$,'42501','active_group_membership_required','leaving revokes reads');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select throws_ok($$select public.group_action(current_setting('test.group')::uuid,'leave')$$,'23514','owner_must_archive_group','owner must explicitly archive rather than orphan group');
select lives_ok($$select public.group_action(current_setting('test.group')::uuid,'archive')$$,'owner can archive group');
select is(jsonb_array_length(public.list_groups()),0,'archived group disappears');
select throws_ok($$select public.list_group_messages_page(current_setting('test.group')::uuid)$$,'42501','active_group_membership_required','archived content inaccessible');
reset role;
update public.profiles set moderation_status='banned' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.create_group('Denied')$$,'42501','active_account_required','banned member cannot create groups');
select * from finish();
rollback;
